steps.snippet:
els = device.elements()
target = next((i for i, e in enumerate(els)
               if e.get('editable') and not (e.get('text') or '').strip()), None)
if target is None:
    raise LookupError("Markor: no empty editable EditText found to type the note text into")
device.input_text(binding['text'], index=target)

index = device.find(text=binding['file_name'], editable=True, clickable=True)
if index is None:
    index = device.find(hint=binding['file_name'], editable=True, clickable=True)
if index is None:
    raise Exception("Note name field not found")
device.click(index)
